import pandas as pd, numpy as np
df = pd.read_csv('/app/bn_sample_10k.csv')
cols = df.columns.tolist()
print("cols:", cols)

# Try pgmpy Gaussian BN estimator
try:
    from pgmpy.models import GaussianBayesianNetwork
    from pgmpy.estimators import BayesianNetworkEstimator
    import warnings; warnings.filterwarnings('ignore')
    nb = GaussianBayesianNetwork()
    est = BayesianNetworkEstimator(df, model_cls=nb)
    # fit with a fixed skeleton to test
    print("pgmpy Gaussian classes available")
except Exception as e:
    import traceback; traceback.print_exc()

# Cross-check parent sets via my DAG: for each node regress on its parents,
# and confirm no other node improves fit (i.e., parents are the Markov blanket)
X = df.values; n=X.shape[0]; idx={c:i for i,c in enumerate(cols)}
def r2(y, regs):
    if not regs: 
        return 0.0, 0.0
    R = X[:,[idx[r] for r in regs]]; A=np.column_stack([np.ones(n),R])
    beta,_,_,_=np.linalg.lstsq(A,y,rcond=None); res=y-A@beta
    ss_res=(res**2).sum(); ss_tot=((y-y.mean())**2).sum()
    return 1-ss_res/ss_tot, res.var(ddof=1)

dag_parents={'U':[], 'Y':['U'], 'R':['U'], 'D':['U','Y'], 'M':['U','R']}
print("\n=== Verify parent sets (R^2 from parents vs best single other) ===")
for node in cols:
    y=X[:,idx[node]]
    r2p, _ = r2(y, dag_parents[node])
    # best single other non-parent
    others=[c for c in cols if c!=node and c not in dag_parents[node]]
    best=(None,-1)
    for o in others:
        r2o,_ = r2(y,[o])
        if r2o>best[1]: best=(o,r2o)
    print(f"  {node}: parents={dag_parents[node]} R2={r2p:.4f} | best-single-other={best[0]} R2={best[1]:.4f}")
